function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPxfSupplierReturns(
  query: Record<string, string | number | boolean>,
): Promise<PxfSupplierReturnListItem[]> {
  const res = await apiClient.get<BffResponse<PxfSupplierReturnListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPxfSupplierReturn(sttRec: string): Promise<PxfSupplierReturn> {
  const res = await apiClient.get<BffResponse<PxfSupplierReturn>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPxfSupplierReturn(body: PxfSupplierReturnWrite): Promise<PxfSupplierReturn> {
  const res = await apiClient.post<BffResponse<PxfSupplierReturn>>(BASE, body);
  return unwrap(res);
}

export async function updatePxfSupplierReturn(sttRec: string, body: PxfSupplierReturnWrite): Promise<PxfSupplierReturn> {
  const res = await apiClient.put<BffResponse<PxfSupplierReturn>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
